def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    # The main diagonal motif is the most frequent non-background color.
    color = max(colors, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                for rr, cc, sr, sc in (
                    (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                    (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
